const ROUTE_KEYS = new Set([
  "localePath",
  "alternateLocalePath",
  "alternateLocaleLabel",
  "alternateLocaleAria",
  "termsPath",
  "privacyPath",
]);

function isTechnicalLeaf(path: string): boolean {
  return path === "productName" ||
    path === "copyright" ||
    /^heroScenarios\[\d+\]\.(id|project|branch|agent)$/.test(path) ||
    /^heroScenarios\[\d+\]\.activity\[\d+\]\.icon$/.test(path) ||
    /^continuityMoments\[\d+\]\.(id|time|activeDevice|icon)$/.test(path) ||
    /^platformReadiness\.[^.]+\.icon$/.test(path) ||
    /^securityPerspectives\[\d+\]\.(id|icon)$/.test(path) ||
    /^connectivityProofs\[(0|1|2|3|5)\]\.label$/.test(path);
}

function routeValue(locale: LocalizedMarketingLocale, key: string): string {
  if (key === "localePath") return localePath(locale);
  if (key === "termsPath") return localePath(locale, "legal/terms");
  if (key === "privacyPath") return localePath(locale, "legal/privacy");
  if (key === "alternateLocalePath") return "/en/";
  if (key === "alternateLocaleAria") {
    return {
      hi: "अंग्रेज़ी में बदलें",
      es: "Cambiar a inglés",
      ar: "التبديل إلى الإنجليزية",
      fr: "Passer à l’anglais",
      bn: "ইংরেজিতে বদলান",
      pt: "Mudar para inglês",
      id: "Beralih ke bahasa Inggris",
      ur: "انگریزی زبان منتخب کریں",
    }[locale];
  }
  return "EN";
}

function translateMarketingValue(
  value: unknown,
  locale: LocalizedMarketingLocale,
  path = "",
): unknown {
  if (path === "heroReplay") return localizedHeroReplay[locale];
  const flow = marketingFlowCopy[locale];
  if (path === "howDescription") return flow.intro;
  if (path === "howTitleAccent") return flow.accent;
  if (path === "securityDescription") return flow.security;
  const flowStep = /^howSteps\[([0-2])\]\.(scope|description)$/.exec(path);
  if (flowStep) {
    return flowStep[2] === "scope"
      ? `0${Number(flowStep[1]) + 1}`
      : flow.steps[Number(flowStep[1])];
  }
  const topLevelKey = path.split(/[.[]/, 1)[0];
  if (path === topLevelKey && Object.hasOwn(CORE_MARKETING_TRANSLATIONS[locale], topLevelKey)) {
    return CORE_MARKETING_TRANSLATIONS[locale][topLevelKey as keyof MarketingCopy];
  }
  if (typeof value === "string") {
    if (ROUTE_KEYS.has(path)) return routeValue(locale, path);
    if (isTechnicalLeaf(path)) return value;
    const translated = MARKETING_STRING_TRANSLATIONS[value]?.[locale];
    if (translated === undefined) {
      throw new Error(`Missing ${locale} marketing translation for ${path}: ${value}`);
    }
    return translated;
  }
  if (Array.isArray(value)) {
    return value.map((item, index) => translateMarketingValue(item, locale, `${path}[${index}]`));
  }
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value).map(([key, item]) => [
        key,
        translateMarketingValue(item, locale, path ? `${path}.${key}` : key),
      ]),
    );
  }
  return value;
}

export const MARKETING_TRANSLATION_OVERRIDES = Object.freeze(
  Object.fromEntries(
    (Object.keys(CORE_MARKETING_TRANSLATIONS) as LocalizedMarketingLocale[]).map((locale) => [
      locale,
      translateMarketingValue(enMarketingCopy, locale) as MarketingCopy,
    ]),
  ) as Record<LocalizedMarketingLocale, MarketingCopy>,
);

function stringLeafCount(value: unknown): number {
  if (typeof value === "string") return 1;
  if (Array.isArray(value)) return value.reduce((count, item) => count + stringLeafCount(item), 0);
  if (value && typeof value === "object") {
    return Object.values(value).reduce<number>((count, item) => count + stringLeafCount(item), 0);
  }
  return 0;
}

const marketingStringLeafTotal = stringLeafCount(enMarketingCopy);

export const MARKETING_TRANSLATION_COVERAGE = Object.freeze(
  Object.fromEntries(
    Object.keys(MARKETING_TRANSLATION_OVERRIDES).map((locale) => [
      locale,
      { translated: marketingStringLeafTotal, total: marketingStringLeafTotal },
    ]),
  ) as Record<LocalizedMarketingLocale, { translated: number; total: number }>,
);

export function localizedMarketingCopy(locale: LocalizedMarketingLocale): MarketingCopy {
  return MARKETING_TRANSLATION_OVERRIDES[locale];
}
